# -*- coding: utf-8 -*-
"""Lot C - Droit, Maths/stats, Informatique, Anglais, Méthodologie (BUT Techniques de commercialisation).

Format 'fiche prototype' identique aux lots A et B : 12 points de cours,
9 questions corrigées, 7 blocs d'affichage, 3 schémas SVG par fiche.
Référentiel : BUT crée par l'arrêté du 11 mars 2020 (BO n12 du 19 mars 2020),
programme national 2022 (arrêté du 15 avril 2022, BO n19 du 12 mai 2022),
textes officiels Légifrance (Code civil, Code de commerce, Code du travail,
Code de la consommation, CPI, RGPD) et CECRL du Conseil de l'Europe.
"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from fixtures import (fiche, qcm, qt, diag, svg_grille, svg_flux, svg_etapes,
                      svg_compare, bloc, valider_et_ecrire)

REF = ("Référentiel BUT « Techniques de commercialisation », arrêté du 11 mars 2020 "
       "(BO n12 du 19 mars 2020) et programme national 2022 (arrêté du 15 avril 2022, "
       "BO n19 du 12 mai 2022) • textes officiels sur Légifrance (Code civil, Code de "
       "commerce, Code du travail, Code de la consommation, Code de la propriété "
       "intellectuelle, règlement UE 2016/679) • CECRL, Conseil de l'Europe • éduscol")
FIL = ["but-tc"]
F = []


def _gloss_qcm(gloss, i):
    """Six QCM corrigés, construits a partir du glossaire du chapitre."""
    n = len(gloss)
    j = i % n
    terme, définition = gloss[j]
    autres = [gloss[(j + k) % n] for k in (1, 2, 3)]
    pos = (i * 2 + 1) % 4
    if i % 3 == 0:
        question = "Que désigne « %s » ?" % terme
        pool = [définition] + [o[1] for o in autres]
    elif i % 3 == 1:
        question = "Quel terme correspond a : « %s » ?" % définition
        pool = [terme] + [o[0] for o in autres]
    else:
        question = "Quelle affirmation décrit correctement « %s » ?" % terme
        pool = [définition] + [o[1] for o in autres]
    options = [""] * 4
    options[pos] = pool[0]
    k = 0
    for idx in range(4):
        if idx != pos:
            options[idx] = pool[k + 1]
            k += 1
    return qcm(question, options, pos,
               définition + " Les autres propositions décrivent d'autres notions du chapitre.")


def A(code, mat, ans, titre, ref, idée, formule, leg, points, gloss,
      scn, txt, etapes, pièges, chiffres, cmp):
    """Ajoute une fiche complète au lot C."""
    questions = [_gloss_qcm(gloss, i) for i in range(6)]
    questions.append(qcm(scn[0], scn[1], scn[2], scn[3]))
    for t in txt:
        questions.append(qt(t[0], t[1], t[2]))
    grille = [["Notion", "Définition", "Repère"]]
    for k, g in enumerate(gloss[:3]):
        grille.append([g[0], g[1], "Notion %d" % (k + 1)])
    retenir = [g[0] + " : " + g[1] for g in gloss[:4]]
    F.append(fiche(
        FIL, ans, mat,
        "Chapitre %s — %s" % (code, titre),
        REF + " • " + ref + " • notions : " + ", ".join(g[0] for g in gloss[:3]),
        points, questions,
        [bloc("L'idée en une phrase", texte=idée, type="intro"),
         bloc("La formule a connaître", eq=formule, leg=leg, type="formule"),
         bloc("Tableau des notions", items=grille, type="grille"),
         bloc("A retenir sur le chapitre", items=retenir, type="liste"),
         bloc("Procéder étape par étape", items=etapes, type="etapes"),
         bloc("Pièges fréquents", items=pièges, type="attention"),
         bloc("En chiffres (a savoir refaire)", items=chiffres, type="exemples")],
        [diag("1 • Repères : " + code,
              svg_grille("Notions clés : " + titre, ["Notion", "Définition", "Repère"],
                         [[g[0], g[1], "Notion %d" % (k + 1)]
                          for k, g in enumerate(gloss[:4])])),
         diag("2 • Procedure : " + code,
              svg_etapes("Méthode : " + titre, etapes)),
         diag("3 • Distinction : " + code,
              svg_compare("Deux notions a distinguer", (cmp[0][0], cmp[0][1]),
                          (cmp[1][0], cmp[1][1])))]))


